import React, { useEffect, useRef } from 'react';
import './Hero.css';

const Hero = () => {
  const heroRef = useRef(null);
  const statsRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('visible');
            if (entry.target === statsRef.current) {
              animateStats();
            }
          }
        });
      },
      { threshold: 0.1, rootMargin: '0px 0px -50px 0px' }
    );

    if (heroRef.current) observer.observe(heroRef.current);
    if (statsRef.current) observer.observe(statsRef.current);

    return () => observer.disconnect();
  }, []);

  const animateStats = () => {
    const statNumbers = document.querySelectorAll('.stat-number[data-count]');
    statNumbers.forEach((stat) => {
      const target = parseInt(stat.dataset.count, 10);
      const duration = 2000;
      const start = performance.now();

      const animate = (currentTime) => {
        const elapsed = currentTime - start;
        const progress = Math.min(elapsed / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3);
        const current = Math.floor(eased * target);
        stat.textContent = current.toLocaleString();
        if (progress < 1) requestAnimationFrame(animate);
      };

      requestAnimationFrame(animate);
    });
  };

  const scrollToSection = (sectionId) => {
    const element = document.getElementById(sectionId);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <section id="hero" className="hero" ref={heroRef} aria-labelledby="hero-title">
      {/* Background Effects */}
      <div className="hero-bg" aria-hidden="true">
        <div className="gradient-orbs" />
        <div className="grid-lines" />
        <div className="hero-pattern" />
      </div>

      <div className="container hero-content">
        <div className="hero-main reveal">
          {/* Badge */}
          <div className="hero-badge reveal reveal-delay-1">
            <span className="badge-dot" aria-hidden="true"></span>
            <span>Junior Data Analyst</span>
            <span className="badge-separator" aria-hidden="true">|</span>
            <span>AWS • Python • Power BI • SQL</span>
          </div>

          {/* Name & Title */}
          <h1 id="hero-title" className="hero-name reveal reveal-delay-2">
            <span className="name-line">Karthik P</span>
          </h1>

          <div className="hero-headline reveal reveal-delay-3">
            <p className="headline-text">
              Transforming data into <span className="highlight">actionable insights</span> through
              <span className="highlight">NLP document processing</span> & <span className="highlight">visual analytics</span>
            </p>
          </div>

          {/* Summary */}
          <div className="hero-summary reveal reveal-delay-4">
            <p>
              Junior Analyst with experience in NLP-based document processing using Amazon Textract (AWS),
              including data review, validation, and quality checks. Skilled in Python, SQL, Excel, Power BI,
              Tableau, statistics, and data visualization.
            </p>
          </div>

          {/* CTA Buttons */}
          <div className="hero-cta reveal reveal-delay-5">
            <button className="btn btn-primary btn-lg" onClick={() => scrollToSection('contact')}>
              <span>Get In Touch</span>
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
                <path d="M5 12h14M12 5l7 7-7 7" />
              </svg>
            </button>
            <button className="btn btn-secondary btn-lg" onClick={() => scrollToSection('projects')}>
              <span>View Projects</span>
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
                <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
                <circle cx="12" cy="12" r="3" />
              </svg>
            </button>
            <a
              href="https://www.linkedin.com/in/karthik-sivam"
              target="_blank"
              rel="noopener noreferrer"
              className="btn btn-ghost btn-lg"
              aria-label="View LinkedIn Profile"
            >
              <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                <path d="M20.447 20.452h-3.554v-5.569c0-1.328-.027-3.037-1.852-3.037-1.853 0-2.136 1.445-2.136 2.939v5.667H9.351V9h3.414v1.561h.046c.477-.9 1.637-1.85 3.37-1.85 3.601 0 4.267 2.37 4.267 5.455v6.286zM5.337 7.433c-1.144 0-2.063-.926-2.063-2.065 0-1.138.92-2.063 2.063-2.063 1.14 0 2.064.925 2.064 2.063 0 1.139-.925 2.065-2.064 2.065zm1.782 13.019H3.555V9h3.564v11.452zM22.225 0H1.771C.792 0 0 .774 0 1.729v20.542C0 23.227.792 24 1.771 24h20.451C23.2 24 24 23.227 24 22.271V1.729C24 .774 23.2 0 22.222 0h.003z"/>
              </svg>
              <span>LinkedIn</span>
            </a>
          </div>

          {/* Stats */}
          <div className="hero-stats reveal reveal-delay-6" ref={statsRef} role="list" aria-label="Key Statistics">
            <div className="stat-item" role="listitem">
              <div className="stat-number" data-count="2">0</div>
              <div className="stat-label">Years Experience</div>
            </div>
            <div className="stat-divider" aria-hidden="true"></div>
            <div className="stat-item" role="listitem">
              <div className="stat-number" data-count="6">0</div>
              <div className="stat-label">Technical Skills</div>
            </div>
            <div className="stat-divider" aria-hidden="true"></div>
            <div className="stat-item" role="listitem">
              <div className="stat-number" data-count="3">0</div>
              <div className="stat-label">Certifications</div>
            </div>
            <div className="stat-divider" aria-hidden="true"></div>
            <div className="stat-item" role="listitem">
              <div className="stat-number" data-count="1">0</div>
              <div className="stat-label">Major Project</div>
            </div>
          </div>
        </div>

        {/* Visual Element */}
        <div className="hero-visual reveal reveal-delay-3" aria-hidden="true">
          <div className="visual-card primary-card">
            <div className="card-glow" />
            <div className="card-content">
              <div className="card-header">
                <div className="card-dots">
                  <span></span><span></span><span></span>
                </div>
              </div>
              <div className="card-body">
                <div className="code-lines">
                  <div className="code-line"><span className="code-keyword">import</span> <span className="code-module">pandas as pd</span></div>
                  <div className="code-line"><span className="code-keyword">import</span> <span className="code-module">aws_textract</span></div>
                  <div className="code-line"><span className="code-comment"># Extract document data</span></div>
                  <div className="code-line"><span className="code-variable">data</span> = <span className="code-function">extract_text</span>(<span className="code-string">"document.pdf"</span>)</div>
                  <div className="code-line"><span className="code-comment"># Validate & clean</span></div>
                  <div className="code-line"><span className="code-variable">clean_data</span> = <span className="code-function">validate</span>(<span className="code-variable">data</span>)</div>
                  <div className="code-line"><span className="code-comment"># Visualize in Power BI</span></div>
                  <div className="code-line"><span className="code-function">dashboard</span>.<span className="code-function">create</span>(<span className="code-variable">clean_data</span>)</div>
                </div>
              </div>
            </div>
          </div>

          <div className="visual-card secondary-card">
            <div className="card-content">
              <div className="card-header">
                <div className="card-dots">
                  <span></span><span></span><span></span>
                </div>
              </div>
              <div className="card-body">
                <div className="chart-placeholder">
                  <svg viewBox="0 0 200 120" className="chart-svg">
                    <defs>
                      <linearGradient id="chartGradient" x1="0" y1="1" x2="0" y2="0">
                        <stop offset="0%" stopColor="var(--color-primary)" stopOpacity="0.3" />
                        <stop offset="100%" stopColor="var(--color-secondary)" stopOpacity="0" />
                      </linearGradient>
                    </defs>
                    <path d="M20,100 L40,70 L60,85 L80,45 L100,60 L120,30 L140,40 L160,20 L180,15" stroke="var(--color-primary)" strokeWidth="2" fill="none" strokeLinecap="round" strokeLinejoin="round" />
                    <path d="M20,100 L40,70 L60,85 L80,45 L100,60 L120,30 L140,40 L160,20 L180,15" stroke="url(#chartGradient)" strokeWidth="2" fill="url(#chartGradient)" fillOpacity="0.3" />
                    <circle cx="40" cy="70" r="4" fill="var(--color-primary)" />
                    <circle cx="80" cy="45" r="4" fill="var(--color-accent)" />
                    <circle cx="120" cy="30" r="4" fill="var(--color-success)" />
                    <circle cx="180" cy="15" r="4" fill="var(--color-secondary)" />
                  </svg>
                </div>
                <div className="chart-labels">
                  <span>Q1</span><span>Q2</span><span>Q3</span><span>Q4</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Scroll Indicator */}
      <div className="scroll-indicator" aria-hidden="true">
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
          <path d="M12 5v14M19 12l-7 7-7-7" />
        </svg>
      </div>
    </section>
  );
};

export default Hero;
